use crate::{model::*,unit_support::*,xq13 as b};
fn path(g:&mut Game,id:&str)->String{fund(g,0,"XQ14",3);let c=held(g,id,0);act(g,0,Action{card_id:Some(c),target_id:Some("society:p0".into()),..Action::new("play")});top(g);g.attachments.last().unwrap().card.id.clone()}
#[test]fn xq13_original_closed_paid_attachment_converts_all_icon_categories(){let mut g=game();let id=field(&mut g,"JC031",0);let enemy=field(&mut g,"JC031",1);let p=path(&mut g,b::ID);for first in [0,1]{g.first_team=first;let c=g.board(&id).unwrap().1;assert_eq!(g.current_icons(c,0),Icons{combat:2,..Default::default()});assert_eq!(g.current_permanent_combat(c,0),2);assert_eq!(g.current_icons(g.board(&enemy).unwrap().1,0).influence,1);restore(&mut g);}g.remove_dead(&p,RemovalCause::Destroy);assert_eq!(g.current_icons(g.board(&id).unwrap().1,0).influence,1);restore(&mut g);}
#[test]fn xq13_second_path_rejected_both_orders_without_payment(){for first in [b::ID,"JC034"]{let mut g=game();path(&mut g,first);let second=held(&mut g,if first==b::ID{"JC034"}else{b::ID},0);fund(&mut g,0,"XQ14",3);let a=Action{card_id:Some(second.clone()),target_id:Some("society:p0".into()),..Action::new("play")};reject(&mut g,0,a);assert!(!g.legal_actions(0).iter().any(|a|a.action.kind=="play"&&a.action.card_id.as_ref()==Some(&second)));}}
#[test]fn xq13_duplicate_corrupt_live_path_rejected_by_game_and_room(){let mut g=game();path(&mut g,b::ID);let mut x=g.clone();let c=x.make_card("JC034",0);x.attachments.push(Attachment{card:c,host_id:"society:p0".into()});assert!(Game::from_persisted(&serde_json::to_string(&x).unwrap()).is_err());let mut r=crate::jc029_tests::envelope(&g);r.game=x;assert!(crate::room::RoomEnvelope::from_persisted(&serde_json::to_string(&r).unwrap()).is_err());}
#[test]fn xq13_live_control_and_hidden_boundary(){let mut g=game();let id=field(&mut g,"JC031",0);path(&mut g,b::ID);g.add_control(&id,1,ControlLifetime::TurnEnd{turn:g.turn},SubtypeChange::None);assert_eq!(g.current_icons(g.board(&id).unwrap().1,0).influence,1);g.control_effects.clear();g.settle_controls();assert_eq!(g.current_icons(g.board(&id).unwrap().1,0).combat,2);assert!(g.hide_in_place(&id));let c=g.regions[0].cards.iter().find(|c|c.definition=="JC031").unwrap();assert_eq!(g.current_icons(c,0),Icons{influence:1,..Default::default()});restore(&mut g);}
fn construct(seed:u64)->Game{use crate::{catalog,deck};let mut d=deck::preset("watchers").unwrap();d.id="closed-xq13-natural".into();d.society_id=Some("MSBQ01".into());d.core_card_id=None;d.cards=[(b::ID,3),("JC031",3),("XQ14",18),("JC125",26)].into_iter().map(|(id,count)|catalog::DeckEntry{card_id:id.into(),count}).collect();assert!(deck::validate(d.clone()).is_err());let mut cards=catalog::catalog().cards.clone();cards.iter_mut().find(|c|c.id==b::ID).unwrap().supported=true;let mut societies=catalog::catalog().societies.clone();societies.iter_mut().find(|s|s.card.id=="MSBQ01").unwrap().card.supported=true;let d=deck::validate_with_registry(d,&cards,&societies).unwrap();let mut other=deck::preset("watchers").unwrap();other.society_id=None;other.core_card_id=None;other.cards=vec![catalog::DeckEntry{card_id:"JC125".into(),count:50}];let other=deck::validate(other).unwrap();let mut g=Game::new("xq13-natural".into(),"LOCAL".into(),"teams".into(),"P0".into(),"watchers".into(),seed).unwrap();for s in 1..4{g.join(format!("P{s}"),"watchers".into()).unwrap();}g.start_validated_decks(vec![d,other.clone(),other.clone(),other]).unwrap();g.drive().unwrap();g}
fn select(g:&Game)->Vec<String>{let p=g.pending.as_ref().unwrap();if matches!(p.resolution,ChoiceResolution::MSBQ01Opening{..}){return vec![p.choice.options[0].id.clone()];}let mut options=p.choice.options.iter().collect::<Vec<_>>();options.sort_by_key(|o|g.players[p.seat].hand.iter().any(|c|c.id==o.id&&matches!(c.definition.as_str(),"XQ13"|"JC031")));options.into_iter().take(p.choice.min.unwrap_or(0)).map(|o|o.id.clone()).collect()}
fn duplicates(mut v:serde_json::Value)->serde_json::Value{for s in v["steps"].as_array_mut().unwrap(){let r=crate::room::RoomEnvelope::from_persisted(s["expected"]["state"].as_str().unwrap()).unwrap();let d=r.transition(s["seat"].as_u64().unwrap()as usize,Some(serde_json::from_value(s["command"].clone()).unwrap()),0).unwrap();assert_eq!(d.outcome,"rejected");assert_eq!(d.state,s["expected"]["state"]);s["duplicate"]=serde_json::to_value(d).unwrap();}v}
#[test]fn xq13_natural_three_blue_assets_attachment_and_prepared_destruction_export(){use crate::abi112_review_play_tests::Trace;let(seed,g)=(1..1025).find_map(|seed|{let g=construct(seed);let mut p=g.clone();while p.pending.is_some(){let ids=select(&p);choose(&mut p,ids);}let h=&p.players[0].hand;[b::ID,"JC031"].iter().all(|id|h.iter().any(|c|&c.definition==id)).then_some((seed,g))}).unwrap();let deck=g.players[0].deck_snapshot.clone().unwrap();let mut t=Trace::new_preserving_rng(g,"xq13-natural-three-blue-assets-and-path".into(),913);let(mut host,mut played)=(false,false);for _ in 0..1400{if t.room.game.pending.is_some(){trace_pending(&mut t);continue;}if played&&t.room.game.stack.is_empty()&&t.room.game.effects.is_empty(){break;}if !t.room.game.stack.is_empty()||t.room.pacing.window.is_some(){t.pass();continue;}let g=&t.room.game;let legal=g.legal_actions(0);let a=if g.players[0].assets.len()<3{legal.iter().find(|a|a.action.kind=="asset"&&a.action.card_id.as_ref().is_some_and(|id|g.players[0].hand.iter().any(|c|&c.id==id&&c.definition=="XQ14")))}else if !host{legal.iter().find(|a|a.action.kind=="deploy"&&a.action.card_id.as_ref().is_some_and(|id|g.players[0].hand.iter().any(|c|&c.id==id&&c.definition=="JC031")))}else{legal.iter().find(|a|a.action.kind=="play"&&a.action.card_id.as_ref().is_some_and(|id|g.players[0].hand.iter().any(|c|&c.id==id&&c.definition==b::ID)))};if let Some(a)=a{if a.action.kind=="deploy"{host=true;}if a.action.kind=="play"{played=true;}t.action(0,a.action.clone());}else{t.pass();}}
assert!(host&&played);let c=t.room.game.regions.iter().flat_map(|r|&r.cards).find(|c|c.definition=="JC031").unwrap();assert_eq!(t.room.game.current_icons(c,t.room.game.board(&c.id).unwrap().0),Icons{combat:2,..Default::default()});let mut natural=t.value();natural["construction"]=serde_json::json!({"deck":deck,"seed":seed,"privateRegistryCandidates":[b::ID,"MSBQ01"],"noLayoutOrResourceMutation":true});let mut g=game();let c=field(&mut g,"JC031",0);let source=path(&mut g,b::ID);fund(&mut g,0,"JC005",2);let spell=held(&mut g,"JC005",0);let mut t=Trace::new_preserving_rng(g,"xq13-prepared-real-strengthened-destruction".into(),914);t.action(0,Action{card_id:Some(spell),target_id:Some(source),..Action::new("play")});for _ in 0..80{if t.room.game.pending.is_some(){trace_pending(&mut t);}else if t.room.game.stack.is_empty()&&t.room.game.effects.is_empty(){break;}else{t.pass();}}assert_eq!(t.room.game.current_icons(t.room.game.board(&c).unwrap().1,0).influence,1);assert!(!t.room.game.attachments.iter().any(|a|a.card.definition==b::ID));let cases=vec![duplicates(natural),duplicates(t.value())];if let Ok(path)=std::env::var("XQ13_NATIVE_OUT"){use sha2::{Digest,Sha256};let mut binding=crate::bq052_tests::source_bindings();for(n,s)in[("rust-game/src/xq13.rs",include_str!("xq13.rs")),("rust-game/src/xq13_tests.rs",include_str!("xq13_tests.rs"))]{binding["files"][n]=format!("{:x}",Sha256::digest(s.as_bytes())).into();}std::fs::write(path,serde_json::to_vec(&serde_json::json!({"catalog":crate::catalog::catalog(),"sourceBindings":binding,"cases":cases})).unwrap()).unwrap();}}

fn trace_pending(t:&mut crate::abi112_review_play_tests::Trace){let p=t.room.game.pending.clone().unwrap();if matches!(p.resolution,ChoiceResolution::Forecast{..}|ChoiceResolution::Frame{choice:FrameChoice::Forecast{..},..}){t.action(p.seat,Action{choice_id:Some(p.choice.id),top:Some(p.choice.options.iter().map(|o|o.id.clone()).collect()),bottom:Some(vec![]),..Action::new("choose")});}else{let ids=select(&t.room.game);t.choose(ids);}}
#[test]fn xq13_response_destination_conflict_uses_original_paid_fizzle(){let mut g=game();fund(&mut g,0,"XQ14",3);let id=held(&mut g,b::ID,0);act(&mut g,0,Action{card_id:Some(id),target_id:Some("society:p0".into()),..Action::new("play")});let after_pay=g.resources(0);let c=g.make_card("JC034",0);g.attachments.push(Attachment{card:c,host_id:"society:p0".into()});restore(&mut g);top(&mut g);assert_eq!(g.resources(0),after_pay);assert_eq!(g.attachments.len(),1);assert_eq!(g.attachments[0].card.definition,"JC034");assert!(g.players[0].graveyard.iter().any(|c|c.definition==b::ID));restore(&mut g);}
#[test]fn xq13_original_identity_catalog_and_personal_not_teammate(){let d=crate::catalog::card(b::ID);assert!(!d.supported);assert_eq!(d.cost,1);assert_eq!(d.loyalty,["蓝色","蓝色","蓝色"]);assert_eq!(d.magic,"鲜血");crate::unit_support::assert_current_serial_catalog();let mut g=game();let teammate=(1..4).find(|s|g.team(*s)==g.team(0)).unwrap();let c=field(&mut g,"JC031",teammate);path(&mut g,b::ID);assert_eq!(g.current_icons(g.board(&c).unwrap().1,0).influence,1);}
